fn choose_odd(v: &Vec<u64>) -> usize {
    // Find the first element that is odd (least significant bit is 1).
    // Since the problem guarantees at least one odd element, unwrap() is safe.
    v.iter()
     .position(|&x| x & 1 == 1)
     .unwrap()
}

